   write: Ex("Bug hunt: `streak(days)` should count the longest run of True values, but it's wrong. Fix it.", "def streak(days):\n    best = 0\n    run = 0\n    for d in days:\n        if d:\n            run += 1\n        best = max(best, run)\n    return best\n", "assert streak([True, True, False, True]) == 2, 'the longest run is 2'\nassert streak([True, False, True, True, True]) == 3, 'the longest run is 3'", "def streak(days):\n    best = 0\n    run = 0\n    for d in days:\n        if d:\n            run += 1\n        else:\n            run = 0\n        best = max(best, run)\n    return best", "What should happen to run when a day is False?"),
   predict: [Pr("x = [1, 2, 3]\ny = x\ny.append(4)\nprint(len(x))", ["4", "3", "Error", "1"], 0, "y = x doesn't copy the list. Both names point at the same list, a classic bug."),
             Pr("def add(item, bag=[]):\n    bag.append(item)\n    return bag\nadd(1)\nprint(add(2))", ["[1, 2]", "[2]", "[1]", "Error"], 0, "A list as a default argument is shared between calls, a famous Python trap. Use bag=None instead.")],
   bug: Ex("Bug hunt: this should print each player's points per game, but one player crashes it. Fix it so 0 games prints 0.", 'stats = [("Ana", 50, 5), ("Ben", 0, 0)]\nfor name, pts, games in stats:\n    print(name, pts / games)\n', "lines = OUT.strip().splitlines()\nassert lines == ['Ana 10.0', 'Ben 0'], 'Ana 10.0, and Ben 0 when he played 0 games'", 'stats = [("Ana", 50, 5), ("Ben", 0, 0)]\nfor name, pts, games in stats:\n    print(name, pts / games if games else 0)', "Guard the division: only divide when games isn't 0."),
